<?php namespace App\Services; use App\Models\Documento; use App\Models\Inventario; use App\Models\MovimientoInventario; use Illuminate\Validation\ValidationException; class InventoryService { public function mover(Documento $documento, int $productoId, int $bodegaId, string $tipo, float $cantidad, ?int $detalleId=null): void { $inventario=Inventario::where(['producto_id'=>$productoId,'bodega_id'=>$bodegaId])->lockForUpdate()->first(); if(!$inventario){$inventario=Inventario::create(['producto_id'=>$productoId,'bodega_id'=>$bodegaId,'stock'=>0]);} $anterior=(float)$inventario->stock; $nuevo=$tipo==='ENTRADA'?$anterior+$cantidad:$anterior-$cantidad; if($nuevo<0) throw ValidationException::withMessages(['inventario'=>'Stock insuficiente para registrar el documento.']); $inventario->update(['stock'=>$nuevo]); MovimientoInventario::create(['documento_id'=>$documento->id,'documento_detalle_id'=>$detalleId,'producto_id'=>$productoId,'bodega_id'=>$bodegaId,'tipo'=>$tipo,'cantidad'=>$cantidad,'stock_anterior'=>$anterior,'stock_nuevo'=>$nuevo,'fecha'=>now(),'user_id'=>$documento->user_id]); } }
